node --import ./node_modules/tsx/dist/loader.mjs --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { globalRegistry } from './providers/registry.ts';
import { handleMultiAgentChatRequest } from './handlers/multiAgentChat.ts';
for (const scenario of ['success', 'failure', 'unknown']) {
  const calls = [];
  const provider = { id: `p-${scenario}`, name: 'mock', type: 'anthropic', supportsImages: () => false,
    async *executeChat(request) {
      calls.push(request);
      if (request.message === 'coordinate' && !request.continuation) {
        yield { type: 'tool_use', toolName: 'delegate_task', toolInput: { agent_id: `worker-${scenario}`, instructions: 'Do work' }, toolUseId: 'call-123' };
      } else if (request.message === 'Do work') {
        if (scenario === 'failure') yield { type: 'error', error: 'worker failed' };
        else { yield { type: 'text', content: 'first ' }; yield { type: 'text', content: 'second' }; }
      } else yield { type: 'text', content: 'continued' };
      yield { type: 'done' };
    }
  };
  globalRegistry.registerProvider(provider);
  globalRegistry.registerAgent({ id: 'orchestrator', name: 'orchestrator', description: '', provider: provider.id });
  if (scenario !== 'unknown') globalRegistry.registerAgent({ id: `worker-${scenario}`, name: 'worker', description: '', provider: provider.id });
  const response = await handleMultiAgentChatRequest({ req: { json: async () => ({ message: 'coordinate', requestId: scenario }) }, var: { config: { debugMode: false } } }, new Map());
  const stream = (await response.text()).trim().split('\n').map(JSON.parse);
  const tool = stream.flatMap(x => x.data?.message?.content || []).find(x => x.type === 'tool_use');
  const continuation = calls.find(x => x.continuation);
  assert.ok(continuation, `${scenario}: continuation missing`);
  const result = JSON.parse(continuation.context.at(-1).content);
  assert.equal(result.type, 'tool_result');
  assert.equal(result.tool_use_id, tool.id);
  assert.equal(result.is_error, scenario !== 'success');
  assert.equal(result.content, scenario === 'success' ? 'first second' : scenario === 'failure' ? 'worker failed' : `Agent 'worker-unknown' not found or provider not available`);
  assert.equal(stream.some(x => x.type === 'error'), scenario === 'unknown');
  console.log(scenario, JSON.stringify({ tool, result, errors: stream.filter(x => x.type === 'error') }));
}
